<?php

namespace SyncBasalam\SalamGate\Admin;

defined('ABSPATH') || exit;

/** Static shipping help. Reading instructions never requires a connected account or HTTP. */
final class HelpContent
{
    public const CATEGORY = 'سلام‌گیت';

    public static function register(): void
    {
        add_action('sync_basalam_help_categories', [self::class, 'renderTab']);
        add_action('sync_basalam_help_sections', [self::class, 'renderSection']);
        add_action('admin_enqueue_scripts', [self::class, 'enqueue'], 30);
        add_action('admin_footer', [self::class, 'renderCompatibilityFragments'], 5);
    }

    public static function renderTab(): void
    {
        if (!current_user_can('manage_options')) return;
        echo '<button type="button" class="basalam-category-tab sg-help-tab" data-category="' . esc_attr(self::CATEGORY)
            . '"><span class="dashicons dashicons-archive" aria-hidden="true"></span> سلام‌گیت</button>';
    }

    public static function renderSection(): void
    {
        if (!current_user_can('manage_options')) return;
        include dirname(__DIR__, 3) . '/templates/SalamGate/help-section.php';
    }

    /** Older base releases have no extension hooks. Render our own fragments
     * only; the local controller moves them into that existing help layout. */
    public static function renderCompatibilityFragments(): void
    {
        if (($_GET['page'] ?? '') !== 'sync_basalam_help' || !current_user_can('manage_options')) return;
        $needsTab = !did_action('sync_basalam_help_categories');
        $needsSection = !did_action('sync_basalam_help_sections');
        if (!$needsTab && !$needsSection) return;
        echo '<div data-sg-help-compatibility hidden>';
        if ($needsTab) self::renderTab();
        if ($needsSection) self::renderSection();
        echo '</div>';
    }

    public static function enqueue(): void
    {
        if (($_GET['page'] ?? '') !== 'sync_basalam_help' || !current_user_can('manage_options')) return;
        $root = dirname(__DIR__, 3);
        $plugin = $root . '/sync-basalam.php';
        wp_enqueue_style('woosalam-salam-gate-help', plugins_url('assets/salam-gate/styles/salam-gate-help.css', $plugin),
            ['basalam-admin-style', 'basalam-admin-font-style'], (string) filemtime($root . '/assets/salam-gate/styles/salam-gate-help.css'));
        wp_enqueue_style('woosalam-salam-gate-icons', plugins_url('assets/salam-gate/styles/salam-gate-icons.css', $plugin),
            ['woosalam-salam-gate-help'], (string) filemtime($root . '/assets/salam-gate/styles/salam-gate-icons.css'));
        wp_enqueue_script('woosalam-salam-gate-help', plugins_url('assets/salam-gate/js/salam-gate-help.js', $plugin),
            ['jquery', 'basalam-admin-help-script'], (string) filemtime($root . '/assets/salam-gate/js/salam-gate-help.js'), true);
    }

